urlset:
{{- /* Homepage */ -}}

  {{ .Site.BaseURL | safeURL }}
  {{ now.Format "2006-01-02T15:04:05Z07:00" }}
  weekly
  1.0


{{- /* All content pages */ -}}
{{- range .Site.Pages }}
  {{- $priority := 0.5 -}}
  {{- if or (eq .Kind "page") (eq .Kind "home") -}}
    {{- $priority = 0.9 -}}
  {{- else if eq .Kind "section" -}}
    {{- $priority = 0.8 -}}
  {{- end -}}

  {{ .Permalink | safeURL }}
  {{- if .Lastmod }}
  {{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}
  {{- end }}
  {{ with .Params.changefreq }}{{ . }}{{ else }}weekly{{ end }}
  {{ with .Params.priority }}{{ . }}{{ else }}{{ $priority }}{{ end }}

{{- end }}
